    def close(self):
        with self.lock:
            if not self._closed:
                self._closed = True
                self.db.close()
            status = payload.get('status', task['status'])
            if status not in ('pendente', 'em_andamento', 'concluida'): raise ServiceError(422, 'INVALID_TASK_STATUS', 'Status de tarefa manual inválido.')
            before = copy.deepcopy(task)
            task.update(status=status, responsavel=str(payload.get('responsavel', payload.get('owner', task.get('responsavel', '')))), comentario=str(payload.get('comentario', payload.get('comment', task.get('comentario', '')))), updated_by=actor, updated_at=_now())
            self.db.execute('UPDATE wf_tasks SET data=? WHERE id=?', (_json(task), task_id))
            self._audit(None, 'checklist_updated', actor, {'before': before, 'after': task})
            return task

    def close(self):
        with self.lock:
            self.stopping = True
            threads = list(self.threads.values())
        for thread in threads:
            if thread is not threading.current_thread(): thread.join(timeout=15)
        with self.lock:
            if not any(t.is_alive() for t in threads): self.db.close()
                raise KnownSendFailure("GOOGLE_REFRESH_FAILED", "Não foi possível renovar a autorização Google. Nenhum envio foi realizado.") from None
            try:
                result = self.provider.send(credentials["access_token"], rawbytes)
            except (KnownSendFailure, SendUncertain):
                raise
            except Exception:
                raise SendUncertain() from None
            if not isinstance(result, dict) or not isinstance(result.get("id"), str) or not result["id"].strip():
                raise SendUncertain()
            return {key: result[key] for key in ("id", "threadId") if isinstance(result.get(key), str)}

    def close(self):
        close = getattr(self.provider, "close", None)
        if close:
            close()

